export function parseArticleSections(raw) {
  if (!raw) return { core: '', main: '', basis: '', source: '' };
  const clean = raw.replace(/\*\*/g, '');
  const coreMatch = clean.match(/【Định điệu cốt lõi】([\s\S]*?)(?=【Luận đoán trọng tâm】|【Căn cứ mệnh bàn】|【Xuất xứ kinh điển】|$)/);
  const mainMatch = clean.match(/【Luận đoán trọng tâm】([\s\S]*?)(?=【Căn cứ mệnh bàn】|【Xuất xứ kinh điển】|$)/);
  const basisMatch = clean.match(/【Căn cứ mệnh bàn】([\s\S]*?)(?=【Xuất xứ kinh điển】|$)/);
  const sourceMatch = clean.match(/【Xuất xứ kinh điển】([\s\S]*?)$/);
  return {
    core: coreMatch?.[1]?.trim() || '',
    main: mainMatch?.[1]?.trim() || '',
    basis: basisMatch?.[1]?.trim() || '',
    source: sourceMatch?.[1]?.trim() || ''
  };
}
